System.register([],function(e,t){"use strict";return{execute:function(){e("f",async()=>{const e=await fetch("https://open.er-api.com/v6/latest/USD");if(!e.ok)throw new Error(`Exchange rate error: ${e.status}`);return(await e.json()).rates.COP}),e("a",async e=>{if(!/^\d{4}-\d{2}-\d{2}$/.test(e))throw new Error("Fecha inválida");const t=encodeURIComponent(`vigenciadesde<='${e}T00:00:00.000'`),r=await fetch(`https://www.datos.gov.co/resource/32sa-8pi3.json?$where=${t}&$order=vigenciadesde DESC&$limit=1`);if(!r.ok)throw new Error(`TRM histórica error: ${r.status}`);const[o]=await r.json();return o?Number(o.valor):null})}}});
